insert into public.aptitude_passages (bank_version, id, title, text) values
  ('1.0.0', 'P1', 'Thandi and the Red Bicycle', 'Thandi has a red bicycle. Every Saturday she rides it to the shop with her brother, Sipho. They buy bread and milk. Then they ride home together.'),
  ('1.0.0', 'P2', 'Rain in the Karoo', 'The Karoo is a dry region in South Africa. Farmers there watch the sky carefully, because rain falls for only a short time each year. When the rain finally comes, dry riverbeds fill with water and small plants bloom quickly across the veld. Within a few weeks the flowers fade, and the land becomes dry again.'),
  ('1.0.0', 'P3', 'The Library Fine', 'The school library has changed its late-return policy. Before, learners paid a fine of R2 for every day a book was overdue. Now they help shelve books for one hour instead. Mr Dlamini, the librarian, says this helps learners understand how books are organised. He also says the fine often stopped poorer learners from borrowing at all.'),
  ('1.0.0', 'P4', 'Checking the News', 'Many people assume a newspaper report is accurate simply because it is printed. However, a careful reader checks whether the report names its sources, whether its claims can be verified, and whether the writer has a stake in the outcome. A report that fails these checks should be treated as an opinion rather than as fact.'),
  ('1.0.0', 'P5', 'The Ripple Effect', 'Economists sometimes describe a multiplier effect. When a town''s largest employer closes, the loss spreads beyond the lost jobs. Shops lose customers, suppliers lose orders, and families spend less, which can cost other workers their jobs too. The effect is strongest in small towns, where few other employers exist to take on displaced workers.')
insert into public.aptitude_items
  (bank_version, id, section, skill, subskill, difficulty, passage_id, stem, options, answer_id) values
  ('1.0.0', 'LIT-01', 'literacy', 'comprehension', 'literal', 1, 'P1', 'What colour is Thandi''s bicycle?', '[{"id":"A","text":"Blue"},{"id":"B","text":"Green"},{"id":"C","text":"Red"},{"id":"D","text":"Yellow"}]'::jsonb, 'C'),
  ('1.0.0', 'LIT-02', 'literacy', 'comprehension', 'literal', 1, 'P1', 'Who rides to the shop with Thandi?', '[{"id":"A","text":"Her mother"},{"id":"B","text":"Her brother, Sipho"},{"id":"C","text":"Her friend"},{"id":"D","text":"Her dog"}]'::jsonb, 'B'),
  ('1.0.0', 'LIT-03', 'literacy', 'comprehension', 'literal', 2, 'P1', 'What do Thandi and Sipho buy at the shop?', '[{"id":"A","text":"Bread and milk"},{"id":"B","text":"Eggs and sugar"},{"id":"C","text":"Juice and rice"},{"id":"D","text":"Sweets and bread"}]'::jsonb, 'A'),
  ('1.0.0', 'LIT-04', 'literacy', 'comprehension', 'literal', 2, 'P2', 'Why do farmers in the Karoo watch the sky carefully?', '[{"id":"A","text":"To count the stars"},{"id":"B","text":"Because rain falls for only a short time each year"},{"id":"C","text":"To find out when the bus arrives"},{"id":"D","text":"Because the sky is always cloudy"}]'::jsonb, 'B'),
  ('1.0.0', 'LIT-05', 'literacy', 'comprehension', 'literal', 2, 'P2', 'What happens to the flowers within a few weeks?', '[{"id":"A","text":"They grow into trees"},{"id":"B","text":"They fade"},{"id":"C","text":"They spread to the river"},{"id":"D","text":"Farmers pick them"}]'::jsonb, 'B'),
  ('1.0.0', 'LIT-06', 'literacy', 'comprehension', 'inference', 3, 'P2', 'What can you infer about the Karoo?', '[{"id":"A","text":"It gets heavy rain all year"},{"id":"B","text":"It is usually dry and gets rain only rarely"},{"id":"C","text":"It is close to the sea"},{"id":"D","text":"It has no plants at all"}]'::jsonb, 'B'),
  ('1.0.0', 'LIT-07', 'literacy', 'comprehension', 'literal', 3, 'P3', 'How much was the old fine for an overdue book?', '[{"id":"A","text":"R2 for every day overdue"},{"id":"B","text":"R2 for every week overdue"},{"id":"C","text":"Nothing, learners were not fined"},{"id":"D","text":"R20 once"}]'::jsonb, 'A'),
  ('1.0.0', 'LIT-08', 'literacy', 'comprehension', 'literal', 4, 'P3', 'What problem with the old fine does the passage mention?', '[{"id":"A","text":"It was too small to matter"},{"id":"B","text":"It often stopped poorer learners from borrowing"},{"id":"C","text":"It was paid to the bus company"},{"id":"D","text":"It was never collected"}]'::jsonb, 'B'),
  ('1.0.0', 'LIT-09', 'literacy', 'comprehension', 'inference', 4, 'P3', 'Which statement is best supported by the passage?', '[{"id":"A","text":"Helping to shelve books can teach learners how books are organised"},{"id":"B","text":"The library has stopped lending books"},{"id":"C","text":"The librarian dislikes poorer learners"},{"id":"D","text":"Learners now never return books late"}]'::jsonb, 'A'),
  ('1.0.0', 'LIT-10', 'literacy', 'comprehension', 'literal', 4, 'P4', 'What does a careful reader check?', '[{"id":"A","text":"Whether the newspaper is expensive"},{"id":"B","text":"Whether the report names its sources"},{"id":"C","text":"Whether the report is long"},{"id":"D","text":"Whether the photos are in colour"}]'::jsonb, 'B'),
  ('1.0.0', 'LIT-11', 'literacy', 'comprehension', 'main-idea', 4, 'P4', 'What is the main point of the passage?', '[{"id":"A","text":"Printed news is always reliable"},{"id":"B","text":"Reports should be checked before being accepted as fact"},{"id":"C","text":"Newspapers should be shorter"},{"id":"D","text":"Writers should avoid giving opinions"}]'::jsonb, 'B'),
  ('1.0.0', 'LIT-12', 'literacy', 'comprehension', 'inference', 5, 'P4', 'How should a report that fails these checks be treated?', '[{"id":"A","text":"As verified fact"},{"id":"B","text":"As an opinion rather than fact"},{"id":"C","text":"As a poem"},{"id":"D","text":"As a secret"}]'::jsonb, 'B'),
  ('1.0.0', 'LIT-13', 'literacy', 'comprehension', 'vocabulary', 5, 'P5', 'As used in the passage, what does ''multiplier effect'' most nearly mean?', '[{"id":"A","text":"Jobs being multiplied by the employer"},{"id":"B","text":"A single loss spreading through the wider local economy"},{"id":"C","text":"Towns doubling their population"},{"id":"D","text":"Workers earning more money"}]'::jsonb, 'B'),
  ('1.0.0', 'LIT-14', 'literacy', 'comprehension', 'literal', 5, 'P5', 'Why is the effect strongest in small towns?', '[{"id":"A","text":"They have more shops"},{"id":"B","text":"Few other employers exist to take on displaced workers"},{"id":"C","text":"They pay higher wages"},{"id":"D","text":"Their employers cannot close"}]'::jsonb, 'B'),
  ('1.0.0', 'LIT-15', 'literacy', 'comprehension', 'main-idea', 5, 'P5', 'Which title best suits the passage?', '[{"id":"A","text":"Why Small Towns Close"},{"id":"B","text":"How One Job Loss Can Ripple Through a Community"},{"id":"C","text":"The History of Local Employers"},{"id":"D","text":"Shops and Their Customers"}]'::jsonb, 'B'),
