  ('1.0.0', 'LOG-IF-01', 'logic', 'if-then', null, 1, null, 'If it rains, the ground gets wet. It is raining. What must be true?', '[{"id":"A","text":"The ground is wet"},{"id":"B","text":"The ground is dry"},{"id":"C","text":"It is sunny"},{"id":"D","text":"It is not raining"}]'::jsonb, 'A'),
  ('1.0.0', 'LOG-IF-02', 'logic', 'if-then', null, 1, null, 'If a child has a library card, they can borrow books. Lerato has a library card. What can Lerato do?', '[{"id":"A","text":"Borrow books"},{"id":"B","text":"Pay R50"},{"id":"C","text":"Close the library"},{"id":"D","text":"Sell books"}]'::jsonb, 'A'),
  ('1.0.0', 'LOG-IF-03', 'logic', 'if-then', null, 2, null, 'All Grade 5 learners write this test. Naledi wrote this test. Is Naledi in Grade 5?', '[{"id":"A","text":"Yes, always"},{"id":"B","text":"No"},{"id":"C","text":"We cannot tell from this information"},{"id":"D","text":"She is in Grade 4"}]'::jsonb, 'C'),
  ('1.0.0', 'LOG-IF-04', 'logic', 'if-then', null, 2, null, 'If the shop is open, Mrs Khumalo buys bread. The shop is closed. Does Mrs Khumalo buy bread?', '[{"id":"A","text":"Yes"},{"id":"B","text":"No"},{"id":"C","text":"Cannot be determined"},{"id":"D","text":"Only on Sundays"}]'::jsonb, 'C'),
  ('1.0.0', 'LOG-IF-05', 'logic', 'if-then', null, 3, null, 'If a shape has four equal sides, it is a rhombus. This shape has four equal sides. What is true?', '[{"id":"A","text":"It is a rhombus"},{"id":"B","text":"It is a circle"},{"id":"C","text":"It has three corners"},{"id":"D","text":"It has no sides"}]'::jsonb, 'A'),
  ('1.0.0', 'LOG-IF-06', 'logic', 'if-then', null, 3, null, 'All mammals breathe air. Whales are mammals. What follows?', '[{"id":"A","text":"Whales breathe water"},{"id":"B","text":"Whales breathe air"},{"id":"C","text":"Mammals are whales"},{"id":"D","text":"Whales cannot breathe"}]'::jsonb, 'B'),
  ('1.0.0', 'LOG-IF-07', 'logic', 'if-then', null, 4, null, 'Thabo runs faster than Lebo. Lebo runs faster than Ayanda. Who runs slowest?', '[{"id":"A","text":"Thabo"},{"id":"B","text":"Lebo"},{"id":"C","text":"Ayanda"},{"id":"D","text":"Cannot be determined"}]'::jsonb, 'C'),
  ('1.0.0', 'LOG-IF-08', 'logic', 'if-then', null, 4, null, 'If A is true, then B is true. B is false. What do we know?', '[{"id":"A","text":"A is true"},{"id":"B","text":"A is false"},{"id":"C","text":"B is true"},{"id":"D","text":"Nothing"}]'::jsonb, 'B'),
  ('1.0.0', 'LOG-IF-09', 'logic', 'if-then', null, 5, null, 'If Zanele arrives before 7:00, she gets a seat. If she gets a seat, she can read the notice. Zanele did not get a seat. What can we say?', '[{"id":"A","text":"She did not arrive before 7:00"},{"id":"B","text":"She arrived before 7:00"},{"id":"C","text":"She can read the notice"},{"id":"D","text":"Nothing can be concluded"}]'::jsonb, 'A'),
  ('1.0.0', 'LOG-IF-10', 'logic', 'if-then', null, 5, null, 'If a number is divisible by 6, it is divisible by 3. 27 is divisible by 3. Is 27 divisible by 6?', '[{"id":"A","text":"Yes"},{"id":"B","text":"No"},{"id":"C","text":"Cannot be determined from the information given"},{"id":"D","text":"Only if it is even"}]'::jsonb, 'C')
